INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (1, 'dc63304a-e153-5105-af5a-6a2ffff229a5', 6, 901, 'আমার পাঁচ বছর বয়সের ছোটো মেয়ে মিনি এক দণ্ড কথা না কহিয়া থাকিতে পারে না। সকালবেলায় আমার নভেলের সপ্তদশ পরিচ্ছেদে হাত দিয়াছি এমন সময় মিনি আসিয়াই আরম্ভ করিয়া দিল, “বাবা, রামদয়াল দরোয়ান কাককে কৌয়া বলছিল, সে কিচ্ছু জানে না। না?” সে আমার লিখিবার টেবিলের পার্শ্বে আমার পায়ের কাছে বসিয়া নিজের দুই হাঁটু এবং হাত লইয়া অতিদ্রুত উচ্চারণে আগডুম-বাগডুম খেলিতে আরম্ভ করিয়া দিল।', 'b364fcdc783679be4af255ff429ded7a81e25acef353c1b64415edb4d4219f9a', 'checked', 'Printed page 1; OCR confidence 89.3%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (2, 'dc63304a-e153-5105-af5a-6a2ffff229a5', 6, 902, 'আমার ঘর পথের ধারে। হঠাৎ মিনি আগডুম-বাগডুম খেলা রাখিয়া জানালার ধারে ছুটিয়া গেল এবং চিৎকার করিয়া ডাকিতে লাগিল, “কাবুলিওয়ালা, ও কাবুলিওয়ালা।”', 'ff41671d226918d9e3c41a3309c22a07db2e11ae6f2b490d13f481f0b7e58f66', 'checked', 'Printed page 1; OCR confidence 89.3%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (3, 'dc63304a-e153-5105-af5a-6a2ffff229a5', 7, 901, 'ময়লা ঢিলা কাপড় পরা, পাগড়ি মাথায়, ঝুলি ঘাড়ে, হাতে গোটাদুই-চার আঙুরের বাক্স, এক লম্বা কাবুলিওয়ালা পথ দিয়া যাইতেছিল— তাহাকে দেখিয়া আমার কন্যারত্নের কিরূপ ভাবোদয় হইল বলা শক্ত, তাহাকে ঊর্ধ্বশ্বাসে ডাকাডাকি আরম্ভ করিয়া দিল। মিনির চিৎকারে যেমনি কাবুলিওয়ালা হাসিয়া মুখ ফিরাইল এবং আমাদের বাড়ির দিকে আসিতে লাগিল, অমনি সে ঊর্ধ্বশ্বাসে অন্তঃপুরে দৌড় দিল, তাহার আর চিহ্ন দেখিতে পাওয়া গেল না।', '009268825b656cbd670bb0a24c64b8ed89b043578ade64b0087e0445798065ca', 'checked', 'Printed page 2; OCR confidence 91.0%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (4, 'dc63304a-e153-5105-af5a-6a2ffff229a5', 7, 902, 'আমি মিনির অমূলক ভয় ভাঙাইয়া দিবার অভিপ্রায়ে তাহাকে অন্তঃপুর হইতে ডাকাইয়া আনিলাম— সে আমার গা ঘেঁষিয়া দাঁড়াইয়া রহিল। কাবুলি ঝুলির মধ্য হইতে কিসমিস, খোবানি বাহির করিয়া তাহাকে দিতে গেল, সে কিছুতেই লইল না, দ্বিগুণ সন্দেহের সহিত আমার হাঁটুর কাছে সংলগ্ন হইয়া রহিল। প্রথম পরিচয়টা এমনি ভাবে গেল।', '35fca42c8c6e60f12c5ce46691234e066556c64f0eff0ce9dca3a6364c720be8', 'checked', 'Printed page 2; OCR confidence 91.0%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (5, 'dc63304a-e153-5105-af5a-6a2ffff229a5', 7, 903, 'দেখিলাম, এই দুটি বন্ধুর মধ্যে গুটিকতক বাঁধা কথা এবং ঠাট্টা প্রচলিত আছে— যথা, রহমতকে দেখিবামাত্র আমার কন্যা হাসিতে হাসিতে জিজ্ঞাসা করিত, “কাবুলিওয়ালা, ও কাবুলিওয়ালা, তোমার ও ঝুলির ভিতর কী?” রহমত একটা অনাবশ্যক চন্দ্রবিন্দু যোগ করিয়া হাসিতে হাসিতে উত্তর করিত, “হাঁতি।”', 'e5c03846a712400abbb82d158c6c10b7af87d3b9694d64e56b35c5b52dcf5b94', 'checked', 'Printed page 2; OCR confidence 91.0%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (6, 'bfbd8358-41b3-5dda-b2c5-af3e9c96813d', 11, 901, 'এক তাঁতি আর তার বউ। তারা বড়োই গরিব। কোনোদিন খায়, কোনোদিন খাইতে পায় না। তাঁত খুঁটি চালাইয়া, কাপড় বুনাইয়া, কীই-বা তাহাদের আয়? আগেকার দিনে তাহারা বেশি উপার্জন করিত। তাহাদের হাতের একখানা শাড়ি পাইবার জন্য কত বাদশাজাদিরা, কত নবাবজাদিরা তাহাদের উঠানে গড়াগড়ি পাড়িত।', 'abda9ae2292da482da4ac2026ce9fc265de7a47e0e8e0950c3f5295596ac19a9', 'checked', 'Printed page 6; OCR confidence 91.3%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (7, 'bfbd8358-41b3-5dda-b2c5-af3e9c96813d', 11, 902, 'তখন একখানা শাড়ি বুননে মাসের পর মাস লাগিত। কোনো কোনো শাড়ি বুনন করতে বৎসরেরও বেশি সময় ব্যয় হইত। সেইসব শাড়ি বুনাইতে কতই-না যত্ন লইতে হইত। রাত থাকিতে উঠিয়া তাঁতির বউ চরকা লইয়া ঘড়র-ঘড়র করিয়া সুতা কাটিত। ভোরবেলায় আলো-আঁধারির মধ্যে সুতা-কাটা শেষ করিতে হইত। সূর্যের আলো যখন চারিদিকে ছড়াইয়া পড়িত, তখন সুতা কাটিলে সুতা তেমন মুলাম হইত না।', '7df2594a60a785c418507c9fae86e0177580c44d3a698f59dd29958d26e6de97', 'checked', 'Printed page 6; OCR confidence 91.3%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (8, '95402820-a31b-54ab-83e6-55a0dabe844b', 23, 901, 'আমরা প্রতিদিন এমন অনেক সমস্যার মুখোমুখি হই, যেগুলো অনুপাত ও সমানুপাতের ধারণা ব্যবহার করে সহজেই সমাধান করা যায়। তাই শিক্ষার্থীদের অনুপাত ও সমানুপাতের ধারণা ও এর প্রয়োগের দক্ষতা অর্জন করা দরকার। একইভাবে, আমাদের দৈনন্দিন জীবনে অনেকখানি জায়গা জুড়ে আছে লেনদেন আর যার সাথে জড়িত লাভ-ক্ষতি।', 'bb65d0e82555fa45fa52d8fe7773c182787c6312326ca084b8656f085afa7c88', 'checked', 'Printed page 18; OCR confidence 92.2%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (9, '95402820-a31b-54ab-83e6-55a0dabe844b', 23, 902, 'বহুরাশিক অনুপাত: মনে করি, একটি বাক্সের দৈর্ঘ্য, প্রস্থ ও উচ্চতা যথাক্রমে ৮ সে.মি., ৫ সে.মি. ও ৬ সে.মি.। দৈর্ঘ্য, প্রস্থ ও উচ্চতার অনুপাত = ৮ : ৫ : ৬। এখানে তিনটি রাশির অনুপাত উপস্থাপন করা হয়েছে। এরূপ তিন বা ততোধিক রাশির অনুপাতকে বহুরাশিক অনুপাত বলে।', '7080b2307ee90817cf2e6f7f1cf1bd998a7179793998a76b08e25b071bef3b82', 'checked', 'Printed page 18; OCR confidence 92.2%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (10, '95402820-a31b-54ab-83e6-55a0dabe844b', 23, 903, 'ধারাবাহিক অনুপাত: মনে করি, পুত্র ও পিতার বয়সের অনুপাত = ১৫ : ৪১ (পূর্ব রাশি : উত্তর রাশি) এবং পিতা ও দাদার বয়সের অনুপাত = ৪১ : ৬৫। দুটি অনুপাতকে একত্র করে পাই, পুত্রের বয়স : পিতার বয়স : দাদার বয়স = ১৫ : ৪১ : ৬৫। এ ধরনের অনুপাতকে ধারাবাহিক অনুপাত বলে। এখানে লক্ষণীয় যে, প্রথম অনুপাতের উত্তর রাশি ও দ্বিতীয় অনুপাতের পূর্ব রাশি সমান। প্রথম অনুপাতের উত্তর রাশি ও দ্বিতীয় অনুপাতের পূর্ব রাশি সমান না হলে তাদেরকে সমান করে ধারাবাহিক অনুপাত বের করতে হয়।', 'e089b48ae26be4188939a63837fbb1d122e0cc61f150276359ad46088d6232d2', 'checked', 'Printed page 18; OCR confidence 92.2%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (11, '95402820-a31b-54ab-83e6-55a0dabe844b', 23, 904, 'দুটি অনুপাতকে ধারাবাহিক অনুপাতে রূপান্তরের জন্য প্রথম অনুপাতের উত্তর রাশি দ্বারা দ্বিতীয় অনুপাতের উভয় রাশিকে গুণ করতে হবে এবং দ্বিতীয় অনুপাতের পূর্ব রাশি দ্বারা প্রথম অনুপাতের উভয় রাশিকে গুণ করতে হবে।', '5089013bff4c329c2872d95d180f79d8188f62c2f06cd84381670f0eb6d177a8', 'checked', 'Printed page 18; OCR confidence 92.2%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (12, '95402820-a31b-54ab-83e6-55a0dabe844b', 24, 901, 'উদাহরণ ১। ৭ : ৫ এবং ৮ : ৯ দুটি অনুপাত। এদেরকে ধারাবাহিক অনুপাতে প্রকাশ কর। সমাধান: ১ম অনুপাত = ৭ : ৫ = ৭ × ৮ : ৫ × ৮ = ৫৬ : ৪০। ২য় অনুপাত = ৮ : ৯ = ৮ × ৫ : ৯ × ৫ = ৪০ : ৪৫। ∴ অনুপাত দুটির ধারাবাহিক অনুপাত ৫৬ : ৪০ : ৪৫।', 'ebb106733e4adba9ca03eab898bdd12eb4a5d851ce5289eea5817366fc0b9369', 'checked', 'Printed page 19; OCR confidence 86.0%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (13, '95402820-a31b-54ab-83e6-55a0dabe844b', 24, 902, 'সমানুপাত: মনে করি, সোহাগ কোনো দোকান থেকে ১০ টাকা দিয়ে একটি চিপসের প্যাকেট এবং ২৫ টাকা দিয়ে ১ কেজি লবণ কিনল। এখানে লবণ ও চিপস্ এর দামের অনুপাত = ২৫ : ১০ বা ৫ : ২। আবার, সোহাগদের শ্রেণিতে শিক্ষার্থীর সংখ্যা ৭০। এদের মধ্যে ছাত্র ৫০জন এবং ছাত্রী ২০জন। এখানে ছাত্র ও ছাত্রীসংখ্যার অনুপাত = ৫০ : ২০ বা ৫ : ২। উভয়ক্ষেত্রে অনুপাত দুটি সমান। অতএব, আমরা বলতে পারি, ২৫ : ১০ = ৫০ : ২০।', 'bfdbcd0103049c96aca381dd72de6355bebdc8eadd847ffefe32e2946e86dfc2', 'checked', 'Printed page 19; OCR confidence 86.0%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (14, '95402820-a31b-54ab-83e6-55a0dabe844b', 24, 903, 'চারটি রাশির ১ম ও ২য় রাশির অনুপাত এবং ৩য় ও ৪র্থ রাশির অনুপাত পরস্পর সমান হলে, রাশি চারটি একটি সমানুপাত তৈরি করে। সমানুপাতের প্রত্যেক রাশিকে সমানুপাতী বলে।', 'd4a65282c45e6e4bf46e7f292d3e2bf83261e1b4836ff682ca74258381d2f06e', 'checked', 'Printed page 19; OCR confidence 86.0%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (15, '41f978e8-eeda-5506-b1ea-dc96ca7fec47', 15, 901, 'প্রাকৃতিক পরিবেশে ক্ষুদ্রাতিক্ষুদ্র জীবদেহ থেকে শুরু করে অতি বৃহদাকার ও উচ্চশ্রেণির উদ্ভিদ ও প্রাণিদেহের সাংগঠনিক এবং কার্যপ্রণালিতে প্রচুর মিল-অমিল রয়েছে। সকল জীবদেহের মধ্যে সাধারণ মিল বা সাদৃশ্যটি হলো যে, জীবদেহ মাত্রই কোষ দ্বারা গঠিত। বিগত কয়েকশ বছর ধরে বিজ্ঞানীগণ নিরলস প্রচেষ্টায় কোষের গঠন, আকৃতি, প্রকৃতি ও অন্যান্য বিষয়ে প্রচুর গবেষণামূলক কাজ করেছেন।', '9c66839796437fee00dddea7db5b762af50aa4d999a09e4a191683018f2e7e26', 'checked', 'Printed page 10; OCR confidence 91.3%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO passages (id, textbook_id, page, seq, text, content_hash, review_status, review_note, publish_status, flags, blocked, provenance, original_text, reviewed_by, reviewed_at, confidence) VALUES (16, '41f978e8-eeda-5506-b1ea-dc96ca7fec47', 15, 902, 'একটি জীবদেহের সব কোষের গঠন প্রকৃতি এক রকম নয় বরং ভিন্ন। আমরা এ পরিচ্ছেদে কোষের গঠন বর্ণনা করব কিন্তু নিম্নে বর্ণিত সকল অঙ্গাণু এক সাথে এক কোষে পাওয়া যায় না। প্রথম দিকে যৌগিক অণুবীক্ষণ যন্ত্রের সাহায্যে জীববিজ্ঞানীরা কোষের যে ধারণা পেয়েছিলেন তা ইলেকট্রন অণুবীক্ষণ যন্ত্র আবিষ্কারের পর আরও সুস্পষ্ট ও বিস্তারিত হয়েছে।', 'eaa5b3fc024a5447832d3c80e22852329e8654e0d08e42d948cfd31c7fe3ba73', 'checked', 'Printed page 10; OCR confidence 91.3%; checked against the page image and corrected; not yet reviewed by a teacher', 'published', NULL, 0, 'checked_seed', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('c5e7785b-04e6-59d7-94ab-9e61a39700fe', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'mcq', '৪ : ৯ এর দ্বিভাজিত অনুপাত কোনটি?', '[{"id":"ক","text":"২ : ৩"},{"id":"খ","text":"৪ : ৯"},{"id":"গ","text":"৯ : ৪"},{"id":"ঘ","text":"১৬ : ৮১"}]', 'ক', NULL, 'বইয়ের উত্তরমালা: (ক)। প্রতিটি রাশির বর্গমূল নিলে √৪ : √৯ = ২ : ৩। ১৬ : ৮১ আসে বর্গ নিলে, যা উল্টো কাজ। এই অধ্যায়ের পাতায় ''দ্বিভাজিত'' শব্দটির সংজ্ঞা নেই; নিশ্চিত না হলে শিক্ষককে জিজ্ঞেস করো।', 'textbook_exercise', 40, NULL, NULL, 1, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'choice', 'দ্বিভাজিত অনুপাতে রাশিগুলো বড় হয় না, ছোট হয়।', NULL, 'ratio-terms', '{"খ":"copied-ratio","গ":"reversed-order","ঘ":"squared-not-rooted"}', '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":1,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-1","printedPage":35}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z') ON CONFLICT DO NOTHING;
INSERT INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('4955cc05-f8de-5448-bcb3-e528430f560a', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'mcq', 'ক : খ = ৪ : ৭ এবং খ : গ = ১০ : ৭ হলে গ : খ : ক = কত?', '[{"id":"ক","text":"৪৯ : ৭০ : ৪০"},{"id":"খ","text":"৪৯ : ৪০ : ৭০"},{"id":"গ","text":"৪০ : ৭০ : ৪৯"},{"id":"ঘ","text":"৪০ : ৪৯ : ৭০"}]', 'ক', NULL, 'ক : খ = ৪ × ১০ : ৭ × ১০ = ৪০ : ৭০, খ : গ = ১০ × ৭ : ৭ × ৭ = ৭০ : ৪৯। তাই ক : খ : গ = ৪০ : ৭০ : ৪৯। প্রশ্ন চেয়েছে উল্টো ক্রমে, গ : খ : ক = ৪৯ : ৭০ : ৪০।', 'textbook_exercise', 40, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'choice', 'আগে ক : খ : গ বের করো, তারপর প্রশ্নের ক্রম দেখো।', NULL, 'continued-ratio', '{"গ":"order-not-reversed","খ":"terms-mismatched","ঘ":"terms-mismatched"}', '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":2,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-2","printedPage":35}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z') ON CONFLICT DO NOTHING;
