INSERT INTO formulas (id, chapter_id, name, name_en, expression, variables, units, explanation, example, source_passage_id, printed_page, provenance, review_status, created_by, created_at, reviewed_by, reviewed_at) VALUES ('c3d1e7a0-0b1e-4c2e-9d41-2a1f00000001', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'দুটি অনুপাতকে ধারাবাহিক অনুপাতে রূপান্তর', 'Joining two ratios into a continued ratio', '$a : b$ ও $c : d$ থেকে $a \times c : b \times c : b \times d$', '[{"symbol":"a : b","meaning":"প্রথম অনুপাত"},{"symbol":"c : d","meaning":"দ্বিতীয় অনুপাত"}]', NULL, 'প্রথম অনুপাতের উভয় রাশিকে দ্বিতীয় অনুপাতের পূর্ব রাশি দিয়ে, আর দ্বিতীয় অনুপাতের উভয় রাশিকে প্রথম অনুপাতের উত্তর রাশি দিয়ে গুণ করলে মাঝের রাশি সমান হয়।', '৭ : ৫ ও ৮ : ৯ থেকে ৫৬ : ৪০ : ৪৫ (পাঠ্যবইয়ের উদাহরণ ১, পৃষ্ঠা ১৯)', 11, 18, 'Rule stated in words in a checked passage, printed page 18; symbols are IntelliHorizon notation of that rule', 'checked', NULL, '2026-11-19T00:00:00Z', NULL, NULL) ON CONFLICT DO NOTHING;
