-- IntelliHorizon seed data: the curriculum registry, the 16 checked passages, questions, topics, formulas and
-- settings exactly as the SQLite migrations created them. Idempotent (ON CONFLICT DO NOTHING).


-- Identity columns continue after the seeded ids.
SELECT setval(pg_get_serial_sequence('evidence', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM evidence), 1), (SELECT COUNT(*) > 0 FROM evidence));
SELECT setval(pg_get_serial_sequence('passages', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM passages), 1), (SELECT COUNT(*) > 0 FROM passages));
SELECT setval(pg_get_serial_sequence('tutor_messages', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM tutor_messages), 1), (SELECT COUNT(*) > 0 FROM tutor_messages));
SELECT setval(pg_get_serial_sequence('attempts', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM attempts), 1), (SELECT COUNT(*) > 0 FROM attempts));
SELECT setval(pg_get_serial_sequence('audit_log', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM audit_log), 1), (SELECT COUNT(*) > 0 FROM audit_log));
SELECT setval(pg_get_serial_sequence('xp_events', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM xp_events), 1), (SELECT COUNT(*) > 0 FROM xp_events));
SELECT setval(pg_get_serial_sequence('passage_reviews', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM passage_reviews), 1), (SELECT COUNT(*) > 0 FROM passage_reviews));
SELECT setval(pg_get_serial_sequence('ai_requests', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM ai_requests), 1), (SELECT COUNT(*) > 0 FROM ai_requests));
SELECT setval(pg_get_serial_sequence('card_reviews', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM card_reviews), 1), (SELECT COUNT(*) > 0 FROM card_reviews));
SELECT setval(pg_get_serial_sequence('twin_feedback', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM twin_feedback), 1), (SELECT COUNT(*) > 0 FROM twin_feedback));
